function twoTeams(graph: number[][]): boolean {
  const n = graph.length;
  const team = new Array<number>(n).fill(-1);
  for (let s = 0; s < n; s++) {
    if (team[s] !== -1) continue;
    team[s] = 0;
    const queue = [s];
    for (let h = 0; h < queue.length; h++) {
      const u = queue[h];
      for (const v of graph[u]) {
        if (team[v] === -1) {
          team[v] = 1 - team[u];
          queue.push(v);
        } else if (team[v] === team[u]) {
          return false;
        }
      }
    }
  }
  return true;
}

