    def twoTeams(self, graph: List[List[int]]) -> bool:
        team = [-1] * len(graph)
        for s in range(len(graph)):
            if team[s] != -1:
                continue
            team[s] = 0
            queue = deque([s])
            while queue:
                u = queue.popleft()
                for v in graph[u]:
                    if team[v] == -1:
                        team[v] = 1 - team[u]
                        queue.append(v)
                    elif team[v] == team[u]:
                        return False
        return True

